using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public sealed class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketInput, TicketPrediction> _predictionEngine;
    private readonly string[] _categoryLabels;
    private readonly ILogger<TicketClassifierService> _logger;

    public TicketClassifierService(ILogger<TicketClassifierService> logger)
    {
        _logger = logger;
        _mlContext = new MLContext(seed: 42);

        var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
        var dataView = _mlContext.Data.LoadFromTextFile<TicketInput>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        _model = TrainModel(dataView);
        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketInput, TicketPrediction>(_model);

        // Extract the ordered label names so we can map Score[] indices to categories.
        var labelBuffer = new VBuffer<ReadOnlyMemory<char>>();
        _predictionEngine.OutputSchema["Score"]
            .GetSlotNames(ref labelBuffer);
        _categoryLabels = labelBuffer.DenseValues()
            .Select(v => v.ToString())
            .ToArray();

        _logger.LogInformation("Model trained with labels: {Labels}", string.Join(", ", _categoryLabels));
    }

    private ITransformer TrainModel(IDataView dataView)
    {
        // Combine Subject + Description into a single text feature, then featurize.
        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketInput.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Training model…");
        return pipeline.Fit(dataView);
    }

    public ClassifyResponse Predict(ClassifyRequest request)
    {
        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(input);

        var scores = new Dictionary<string, float>();
        for (int i = 0; i < _categoryLabels.Length; i++)
        {
            scores[_categoryLabels[i]] = prediction.Score[i];
        }

        return new ClassifyResponse
        {
            PredictedCategory = prediction.Category,
            Scores = scores
        };
    }

    public EvaluationResponse Evaluate()
    {
        var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
        var dataView = _mlContext.Data.LoadFromTextFile<TicketInput>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // Re-apply the label key mapping so the evaluator can compare predictions.
        var predictions = _model.Transform(dataView);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");

        return new EvaluationResponse
        {
            MacroAccuracy = (float)metrics.MacroAccuracy,
            MicroAccuracy = (float)metrics.MicroAccuracy,
            LogLoss = (float)metrics.LogLoss,
            LogLossReduction = (float)metrics.LogLossReduction
        };
    }
}

