using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketClassifierController(TicketClassifierService classifier) : ControllerBase
{
    /// <summary>POST /api/ticketclassifier/classify – predict the category for a ticket.</summary>
    [HttpPost("classify")]
    public ActionResult<ClassifyResponse> Classify([FromBody] ClassifyRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) && string.IsNullOrWhiteSpace(request.Description))
            return BadRequest("Subject or Description must be provided.");

        if (request.Priority is < 1 or > 3)
            return BadRequest("Priority must be between 1 and 3.");

        return Ok(classifier.Predict(request));
    }

    /// <summary>GET /api/ticketclassifier/evaluate – return model evaluation metrics.</summary>
    [HttpGet("evaluate")]
    public ActionResult<EvaluationResponse> Evaluate() => Ok(classifier.Evaluate());
}

